export function createCalculator() {
    let currentValue = 0;
    let memoryValue = 0;

    const add = (value: number): Calculator => {
        currentValue += value;
        return { currentValue, memoryValue };
    };

    const subtract = (value: number): Calculator => {
        currentValue -= value;
        return { currentValue, memoryValue };
    };

    const multiply = (value: number): Calculator => {
        currentValue *= value;
        return { currentValue, memoryValue };
    };

    const divide = (value: number): Calculator => {
        if (value === 0) throw new Error("Cannot divide by zero");
        currentValue /= value;
        return { currentValue, memoryValue };
    };

    const clear = (): Calculator => {
        currentValue = 0;
        return { currentValue, memoryValue };
    };

    const result = (): number => currentValue;

    const memoryStore = (): Calculator => {
        memoryValue = currentValue;
        return { currentValue, memoryValue };
    };

    const memoryAdd = (): Calculator => {
        memoryValue += currentValue;
        return { currentValue, memoryValue };
    };

    const memoryClear = (): Calculator => {
        memoryValue = 0;
        return { currentValue, memoryValue };
    };

    const memoryRecall = (): number => memoryValue;

    return {
        add: (value) => ({ ...createCalculator(), add(value) }),
        subtract: (value) => ({ ...createCalculator(), subtract(value) }),
        multiply: (value) => ({ ...createCalculator(), multiply(value) }),
        divide: (value) => ({ ...createCalculator(), divide(value) }),
        clear: () => createCalculator(),
        result,
        memoryStore: () => ({ ...createCalculator(), memoryStore() }),
        memoryAdd: () => ({ ...createCalculator(), memoryAdd() }),
        memoryClear: () => ({ ...createCalculator(), memoryClear() }),
        memoryRecall
    };
}
