import { writable } from 'svelte/store';

function createTodoApp() {
  const todos = writable([]);

  function addTodo(text: string): { id: number, text: string, completed: boolean } {
    let newId = (todos.subscribe(todosArray => todosArray.length) || 0);
    const newTodo = { id: newId, text, completed: false };
    todos.update(currentTodos => [...currentTodos, newTodo]);
    return newTodo;
  }

  function getTodo(id: number): { id: number, text: string, completed: boolean } | undefined {
    return todos.subscribe(todosArray => todosArray.find(todo => todo.id === id));
  }

  function toggleTodo(id: number): void {
    todos.update(currentTodos =>
      currentTodos.map(todo => (todo.id === id ? { ...todo, completed: !todo.completed } : todo))
    );
  }

  function deleteTodo(id: number): boolean {
    const index = todos.subscribe(todosArray => todosArray.findIndex(todo => todo.id === id));
    if (index !== -1) {
      todos.update(currentTodos => currentTodos.filter(todo => todo.id !== id));
      return true;
    }
    return false;
  }

  function listTodos(): Array<{ id: number, text: string, completed: boolean }> {
    return todos.subscribe(todosArray => [...todosArray]);
  }

  function listCompleted(): Array<{ id: number, text: string, completed: boolean }> {
    return listTodos().filter(todo => todo.completed);
  }

  function listPending(): Array<{ id: number, text: string, completed: boolean }> {
    return listTodos().filter(todo => !todo.completed);
  }

  function clearCompleted(): void {
    todos.update(todosArray => todosArray.filter(todo => !todo.completed));
  }

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
}

export { createTodoApp };
```

```typescript
export function createTodoApp(): TodoApp {
  let nextId = 1;
  const todos: Record<number, Todo> = {};

  function addTodo(text: string): Todo {
    const todo = { id: nextId++, text, completed: false };
    todos[todo.id] = todo;
    return todo;
  }

  function getTodo(id: number): Todo | undefined {
    if (todos[id]) {
      return todos[id];
    }
    return undefined;
  }

  function toggleTodo(id: number): void {
    const todo = getTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  }

  function deleteTodo(id: number): boolean {
    if (todos[id]) {
      delete todos[id];
      return true;
    }
    return false;
  }

  function listTodos(): Todo[] {
    const allTodos = Object.values(todos);
    return allTodos.sort((a, b) => a.id - b.id);
  }

  function listCompleted(): Todo[] {
    return listTodos().filter(todo => todo.completed);
  }

  function listPending(): Todo[] {
    return listTodos().filter(todo => !todo.completed);
  }

  function clearCompleted(): void {
    Object.keys(todos).forEach(key => {
      if (todos[parseInt(key)].completed) {
        delete todos[parseInt(key)];
      }
    });
  }

  const todoApp: TodoApp = {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };

  return todoApp;
}
