export function createTodoApp(): TodoApp {
  const todos: Todo[] = [];
  let nextId = 0;

  function addTodo(text: string): Todo {
    const id = nextId++;
    const newTodo = { id, text, completed: false };
    todos.push(newTodo);
    return newTodo;
  }

  function getTodo(id: number): Todo | undefined {
    for (const todo of todos) {
      if (todo.id === id) {
        return todo;
      }
    }
    return undefined;
  }

  function toggleTodo(id: number): void {
    for (let i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        return;
      }
    }
  }

  function deleteTodo(id: number): boolean {
    for (let i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        const removed = todos.splice(i, 1);
        return true;
      }
    }
    return false;
  }

  function listTodos(): Todo[] {
    return todos;
  }

  function listCompleted(): Todo[] {
    const completed: Todo[] = [];
    for (const todo of todos) {
      if (todo.completed) {
        completed.push(todo);
      }
    }
    return completed;
  }

  function listPending(): Todo[] {
    const pending: Todo[] = [];
    for (const todo of todos) {
      if (!todo.completed) {
        pending.push(todo);
      }
    }
    return pending;
  }

  function clearCompleted(): void {
    for (let i = 0; i < todos.length; i++) {
      if (todos[i].completed) {
        todos.splice(i, 1);
        i--; // adjust index after removal
      }
    }
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}
