```typescript
export function createTodoApp(): {
  addTodo(text: string): { id: number; text: string; completed: boolean } | null;
  getTodo(id: number): { id: number; text: string; completed: boolean } | undefined;
  toggleTodo(id: number): void;
  deleteTodo(id: number): boolean;
  listTodos(): { id: number; text: string; completed: boolean }[];
  listCompleted(): { id: number; text: string; completed: boolean }[];
  listPending(): { id: number; text: string; completed: boolean }[];
  clearCompleted(): void;
} {
  let nextId = 1;

  const todos: { [id: number]: { id: number; text: string; completed: boolean } } = {};

  function addTodo(text: string): { id: number; text: string; completed: boolean } | null {
    if (text === '') return null;
    if (!(text in todos)) nextId += 1;
    todos[nextId] = { id: nextId, text, completed: false };
    return todos[nextId];
  }

  function getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
    return todos[id];
  }

  function toggleTodo(id: number): void {
    if (id in todos) {
      const todo = todos[id];
      delete todos[id];
      todos[todo.id] = { ...todo, completed: !todo.completed };
    }
  }

  function deleteTodo(id: number): boolean {
    return id in todos && delete todos[id];
  }

  function listTodos(): { id: number; text: string; completed: boolean }[] {
    return Object.values(todos);
  }

  function listCompleted(): { id: number; text: string; completed: boolean }[] {
    const filtered = {};
    for (const todo of todos) if (todo.completed) filtered[todo.id] = todo;
    return Object.values(filtered);
  }

  function listPending(): { id: number; text: string; completed: boolean }[] {
    const filtered = [];
