class CalculatorImpl {
  private current = 0;
  private memory = 0;

  add(n: number): CalculatorImpl {
    this.current += n;
    return this;
  }

  subtract(n: number): CalculatorImpl {
    this.current -= n;
    return this;
  }

  multiply(n: number): CalculatorImpl {
    this.current *= n;
    return this;
  }

  divide(n: number): CalculatorImpl {
    if (n === 0) {
      throw new Error('Division by zero');
    }
    this.current /= n;
    return this;
  }

  clear(): CalculatorImpl {
    this.current = 0;
    return this;
  }

  result(): number {
    return this.current;
  }

  memoryStore(): CalculatorImpl {
    this.memory = this.current;
    return this;
  }

  memoryRecall(): number {
    return this.memory;
  }

  memoryClear(): CalculatorImpl {
    this.memory = 0;
    return this;
  }

  memoryAdd(): CalculatorImpl {
    this.memory += this.current;
    return this;
  }
}

export function createCalculator(): Calculator {
  return new CalculatorImpl();
}
