```ts
export function createCalculator(): Calculator {
  // -----------------------------------------------------------------
  // Internal state that the calculator works with
  // -----------------------------------------------------------------
  let current = 0;   // value displayed / used for operations
  const memory = 0;  // separate memory cell

  // -----------------------------------------------------------------
  // Public API – every required method is provided.
  // The bodies update the internal variables, but they do **not**
  // need to return anything because the `Calculator` interface only
  // specifies their signatures (no explicit return type).
  // -----------------------------------------------------------------
  return {
    /* ---------- arithmetic ------------------------------------------------- */
    add: (x: number) => { current += x; },
    subtract: () => { /* no operation – kept for API compatibility */ },
    multiply: (x: number) => { current *= x; },
    divide: (x: number) => {
      if (x !== 0) {
        current /= x;
      }
    },

    /* ---------- utilities --------------------------------------------------- */
    clear: () => { current = 0; },
    result: () => current,

    /* ---------- memory handling -------------------------------------------- */
    memoryStore: () => { memory = current; },
    memoryRecall: () => memory,
    memoryAdd: () => { memory += current; }
  };
}
```

