export function createTodoApp(): TodoApp {
    let nextId = 1;
    const todos: Todo[] = [];
    const deletedIds = new Set<number>();

    return {
        addTodo(text: string): Todo {
            const id = nextId++;
            todos.push({ id, text, completed: false });
            return { id, text, completed: false };
        },

        getTodo(id: number): Todo | undefined {
            return todos.find(todo => todo.id === id && !deletedIds.has(id));
        },

        toggleTodo(id: number): void {
            const todo = todos.find(todo => todo.id === id && !deletedIds.has(id));
            if (todo) todo.completed = !todo.completed;
        },

        deleteTodo(id: number): boolean {
            if (todos.some(todo => todo.id === id && !deletedIds.has(id))) {
                deletedIds.add(id);
                return true;
            }
            return false;
        },

        listTodos(): Todo[] {
            return todos.filter(todo => !deletedIds.has(todo.id));
        },

        listCompleted(): Todo[] {
            return todos.filter(todo => !deletedIds.has(todo.id) && todo.completed);
        },

        listPending(): Todo[] {
            return todos.filter(todo => !deletedIds.has(todo.id) && !todo.completed);
        },

        clearCompleted(): void {
            todos.forEach(todo => {
                if (todo.completed && !deletedIds.has(todo.id)) {
                    deletedIds.add(todo.id);
                }
            });
        }
    };
}

