  function listPending(): Array<{ id: number; text: string; completed: boolean }> {
    return todos.filter(todo => !todo.completed);
  }

  function clearCompleted(): void {
    const remaining = todos.filter(todo => !todo.completed);
    todos.length = 0;
    todos.push(...remaining);
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
