import { Calculator } from './Calculator';

export function createCalculator(): Calculator {
  let currentValue = 0;
  let memoryValue = 0;

  class InternalCalculator implements Calculator {
    add(n: number): Calculator {
      currentValue += n;
      return this;
    }

    subtract(n: number): Calculator {
      currentValue -= n;
      return this;
    }

    multiply(n: number): Calculator {
      currentValue *= n;
      return this;
    }

    divide(n: number): Calculator {
      if (n === 0) throw new Error('Cannot divide by zero.');
      currentValue /= n;
      return this;
    }

    clear(): Calculator {
      currentValue = 0;
      return this;
    }

    result(): number {
      return currentValue;
    }

    memoryStore(): Calculator {
      memoryValue = currentValue;
      return this;
    }

    memoryRecall(): number {
      return memoryValue;
    }

    memoryClear(): Calculator {
      memoryValue = 0;
      return this;
    }

    memoryAdd(): Calculator {
      if (memoryValue !== 0) memoryValue += currentValue;
      return this;
    }
  }

  return new InternalCalculator();
