export function createTodoApp() {
  let counter = 0;
  const todos = new Map<number, { id: number; text: string; completed: boolean }>();

  function addTodo(text: string) {
    const id = ++counter;
    const todo = { id, text, completed: false };
    todos.set(id, todo);
    return todo;
  }

  function getTodo(id: number) {
    return todos.get(id);
  }

  function toggleTodo(id: number) {
    const todo = todos.get(id);
    if (todo !== undefined) {
      todo.completed = !todo.completed;
    }
  }

  function deleteTodo(id: number): boolean {
    return todos.delete(id);
  }

  function listTodos() {
    return Array.from(todos.values());
  }

  function listCompleted() {
    const result: typeof listTodos = Array.from(todos.values()).filter(todo => todo.completed);
    return result;
  }

  function listPending() {
    const result: typeof listTodos = Array.from(todos.values()).filter(todo => !todo.completed);
    return result;
  }

  function clearCompleted() {
    const completedTodos = Array.from(todos.values()).filter(todo => todo.completed);
    for (const todo of completedTodos) {
      todos.delete(todo.id);
    }
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}
