/**
 * Creates a calculator instance with basic arithmetic operations and memory functions.
 *
 * Features:
 * - Arithmetic: add, subtract, multiply, divide
 * - Result management: result() to get current value
 * - Memory functions: store, add to, clear, and recall memory
 * - Chaining support via method returns
 *
 * @returns {CalculatorInstance} Calculator instance with exposed methods.
 */
export function createCalculator() {
  let value = 0; // Current calculator value
  let memory = 0; // Calculator memory

  /**
   * Adds a number to the current value.
   *
   * @param num - Number to add.
   * @returns {CalculatorInstance} The calculator instance for chaining.
   */
  function add(num: number) {
    value += num;
    return this;
  }

  /**
   * Subtracts a number from the current value.
   *
   * @param num - Number to subtract.
   * @returns {CalculatorInstance} The calculator instance for chaining.
   */
  function subtract(num: number) {
    value -= num;
    return this;
  }

  /**
   * Multiplies the current value by a number.
   *
   * @param num - Multiplier.
   * @returns {CalculatorInstance} The calculator instance for chaining.
   */
  function multiply(num: number) {
    value *= num;
    return this;
  }

  /**
   * Divides the current value by a number.
   *
   * @param num - Divisor. Throws an error if zero.
   * @returns {CalculatorInstance} The calculator instance for chaining.
   * @throws {Error} When dividing by zero.
   */
  function divide(num: number) {
    if (num === 0) {
      throw new Error("Division by zero");
    }
    value /= num;
    return this;
  }

  /**
   * Clears the current value to 0.
   *
