export function createTodoApp(): TodoApp {
  let todos: [{ id: number; text: string; completed: boolean }][] = [];
  const nextId = (todos.length === 0) ? 1 : Math.max(...todos.map(todo => todo.id)) + 1;

  export async function addTodo(text: string): Promise<{ id: number; text: string; completed: false }> {
    return { id: nextId, text, completed: false };
  }

  export function getTodo(id: number): Todo | undefined {
    for (const todo of todos) {
      if (todo.id === id) {
        return todo;
      }
    }
    return undefined;
  }

  export async function toggleTodo(id: number): Promise<void> {
    const todo = getTodo(id);
    if (todo && todo.completed) {
      todos[todos.findIndex(t => t.id === id)].completed = false;
    } else {
      // doing nothing
    }
  }

  export async function deleteTodo(id: number): Promise<boolean> {
    if (getTodo(id)) {
      const index = todos.indexOf(getTodo(id));
      return todos.splice(index, 1).length > 0;
    }
    return false;
  }

  export async function listTodos(): Promise<{ id: number; text: string; completed: boolean }[]> {
    return todos.map(todo => ({ ...todo }));
  }

  export async function listCompleted(): Promise<{ id: number; text: string; completed: boolean }[]> {
    return todos.filter(todo => todo.completed);
  }

  export async function listPending(): Promise<{ id: number; text: string; completed: boolean }[]> {
    return todos.filter(todo => !todo.completed);
  }

  export async function clearCompleted(): Promise<void> {
    let i = 0;
    while (i < todos.length) {
      if (todos[i].completed) {
        todos.splice(i, 1);
      } else {
        i++;
      }
    }
  }
}
