  const todos: Record<number, Todo> = {}; // Internal todo storage with unique keys

  function addTodo(text: string): { id: number; text: string; completed: boolean } {
    const newId = nextId++;
    const todo = { id: newId, text, completed: false };
    todos[newId] = todo;
    return todo;
  }

  function getTodo(id: number): Todo | undefined {
    if (todos[id]) return todos[id];
    return undefined; // Returns when no todo
  }

  function toggleTodo(id: number): void {
    const todo = getTodo(id);
    if (todo) todo.completed = !todo.completed;
  }

  function deleteTodo(id: number): boolean {
    if (!todos[id]) return false; // Returns false on non-existant id
    delete todos[id];
    return true;
  }

  function listTodos(): Array<Todo> {
    const todoKeys = Object.keys(todos).map(Number);
    const list: Todo[] = [];
    for (const key of todoKeys) {
      if (!todos[key]) continue; // Skip deleted non-existant keys
      list.push(todos[key]);
    }
    return list;
  }

  function listCompleted(): Array<Todo> {
    const todosListed = Object.values(todos);
    return todosListed.filter(todo => todo.completed === true); // Completed only
  }

  function listPending(): Array<Todo> {
    const todosListed = Object.values(todos);
    return todosListed.filter(todo => !todo.completed); // Pending only (negation of completed)
  }

  function clearCompleted(): void {
    const pendingTodos: Record<number, Todo> = {};
    for (const id in todos) {
      if (!todos[id].completed) {
        pendingTodos[Number(id)] = todos[id];
      }
    }
    todos = pendingTodos; // Reassign to only non-completed
  }

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted: listPending(), clearCompleted };
}

