// todo-app.ts
/**
 * A simple todo application module that provides a function to create
 * a todo list management system with all required operations.
 */
export function createTodoApp() {
  // Internal state encapsulated within the app
  let nextId = 1;
  const todosMap = new Map<number, { id: number; text: string; completed: boolean }>();

  /**
   * Adds a new todo item to the list.
   */
  function addTodo(text: string): { id: number; text: string; completed: boolean } {
    if (!text.trim()) {
      throw new Error('Todo text cannot be empty.');
    }
    const id = nextId++;
    const todo = { id, text, completed: false };
    todosMap.set(id, todo);
    return todo;
  }

  /**
   * Retrieves a todo item by its ID.
   */
  function getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
    return todosMap.get(id);
  }

  /**
   * Toggles the completion state of a todo item.
   */
  function toggleTodo(id: number): void {
    const todo = todosMap.get(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  }

  /**
   * Deletes a todo item by its ID.
   */
  function deleteTodo(id: number): boolean {
    return todosMap.delete(id);
  }

  /**
   * Returns the list of all todos.
   */
  function listTodos(): Array<{ id: number; text: string; completed: boolean }> {
    return Array.from(todosMap.values());
  }

  /**
   * Returns the list of completed todos.
   */
  function listCompleted(): Array<{ id: number; text: string; completed: boolean }> {
    return Array.from(todosMap.values()).filter((todo) => todo.completed);
  }

  /**
   * Returns the list of pending (incomplete) todos.
   */
  function listPending(): Array<{ id: number; text: string; completed: boolean }> {
    return Array.from(todosMap.values()).filter((todo) => !todo.completed);
  }

  /**
   * Removes all completed todos.
   */
  function clearCompleted(): void {
    const completedIds = Array.from(todosMap.entries())
      .filter(([, todo]) => todo.completed)
      .map(([id]) => id);
    completedIds.forEach((id) => todosMap.delete(id));
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}

