```typescript
class TodoApp implements TodoApp {
  private idCounter = 0;
  private deletedIds: Set<number> = new Set();
  private todos: Todo[] = [];

  constructor() {}

  addTodo(text: string): Todo {
    const id = this.idCounter++;
    const todo: Todo = {
      id,
      text,
      completed: false
    };

    // Add to the list of todos
    this.todos.push(todo);

    // Remove from deletedIds if already in it
    if (this.deletedIds.has(id)) {
      this.deletedIds.delete(id);
    }

    return todo;
  }

  deleteTodo(id: number): boolean {
    if (this.deletedIds.has(id)) {
      this.deletedIds.delete(id);
      return true;
    } else {
      // If not deleted, add back to the list
      const todo: Todo = {
        id,
        text: "Untitled",
        completed: false
      };
      this.todos.push(todo);
      this.deletedIds.delete(id);
      return false;
    }
  }

  listTodos(): Todo[] {
    return this.todos;
  }

  listCompleted(): Todo[] {
    return this.todos.filter(todo => todo.completed);
  }

  listPending(): Todo[] {
    return this.todos.filter(todo => !todo.completed);
  }

  clearCompleted(): void {
    this.todos = this.todos.filter(todo => !todo.completed);
  }
}
```

