  const todos: Todo[] = [];

  return {
    addTodo: (text: string): Todo => {
      const id = todos.length + 1;
      const newTodo: Todo = { id, text, completed: false };
      todos.push(newTodo);
      return newTodo;
    },
    getTodo: (id: number): Todo | undefined => todos.find(todo => todo.id === id),
    toggleTodo: (id: number): void => {
      const updatedTodos = todos.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      );
      todos.splice(todos.findIndex(todo => todo.id === id), 1, ...updatedTodos.filter((_, index) => index === todos.findIndex(todo => todo.id === id)));
    },
    deleteTodo: (id: number): boolean => {
      const initialLength = todos.length;
      todos = todos.filter(todo => todo.id !== id);
      return todos.length !== initialLength;
    },
    listTodos: (): Todo[] => [...todos],
    listCompleted: (): Todo[] => [...todos.filter(todo => todo.completed)],
    listPending: (): Todo[] => [...todos.filter(todo => !todo.completed)],
    clearCompleted: (): void => {
      const updatedTodos: Todo[] = todos.filter(todo => !todo.completed);
      const replacedIndices: Set<number> =new Set();
      todos.forEach((todo, index) => {
        if (!todo.completed) replacedIndices.add(index);
      });
      updatedTodos.forEach((todo, index) => {
        const originalTodo = todos[replacedIndices.has(index) ? index : index + 1];
        todos[index] = {...originalTodo, completed: false};
        if (index + 1 >= updatedTodos.length && replacedIndices.has(index)) {
          todos.splice(updatedTodos.length, replacedIndices.has(index+1) ? 1 : 0);
        }
      });
    }
  };
}
